window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-381e523b53e2290b"]={"versions": [{"id": "FIG-381e523b53e2290b", "releases": ["R21-11", "R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> System- und Komponenten-Architekturdiagramm (Deployment- und Integrationsszenario).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der verteilten Aktualisierung von Classic-AUTOSAR- und Non-AUTOSAR-Steuergeräten über das fahrzeugzentrale Update- und Konfigurationsmanagement (Vehicle-UCM / V-UCM) der Adaptive Platform unter Verwendung eines externen Werkstattesters (<em>Garage Tester</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Zeigt die Entkopplung zwischen externem Diagnosezugang und interner Flash-Orchestrierung. Der externe Tester flasht Sub-ECUs nicht direkt; stattdessen agiert eine bordeigene <code>Diagnostic application</code> als lokaler Client (äquivalent zu einem Cloud-basierten OTA-Client), der den <code>UCM Master</code> zur fahrzeugweiten Kampagnenausführung triggert. Die physische Reprogrammierung heterogener Ziel-ECUs wird über einen <code>Flashing Adapter</code> via standardisierter <code>ISO 22900-2 (D-PDU API)</code> gekapselt.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Externe Diagnose-Infrastruktur</p>\n<ul class=\"fig-list\">\n<li><strong>Garage tester:</strong> Off-Board-Diagnosetester, physikalisch über ein <code>Communication medium</code> angebunden.</li>\n<li><strong>Communication channel:</strong> Fahrzeug-Gateway-Zugang via Ethernet oder CAN/DoCAN-Bus.</li>\n</ul>\n<p class=\"fig-p\">#### Adaptive AUTOSAR Machine (Host für V-UCM)</p>\n<ul class=\"fig-list\">\n<li><strong>Applikationsebene (Adaptive Applications):</strong></li>\n<li><code>Diagnostic application</code>: Adaptiver Service/Prozess; nimmt Diagnoseanfragen des Testers entgegen und agiert gegenüber dem <code>UCM Master</code> als Update-Client (<em>acts like an OTA Client</em>).</li>\n<li><code>Flashing Adapter</code>: Applikative Schicht zur Kapselung herstellerspezifischer UDS-Flasbabläufe (Download-Sequenzen, Signature-Checks) für externe Ziel-Steuergeräte.</li>\n<li><code>Vehicle State Manager (VSM)</code>: Überwacht und validiert fahrzeugweite Sicherheitszustände (z. B. Stillstand, Klemmenstatus, Batterie-Mindestspannung).</li>\n<li><code>Driver Interface</code>: Applikation zur Benutzerinteraktion (Fahrerquittierung, Statusanzeigen).</li>\n<li><strong>Plattform-/Cluster-Ebene (Adaptive Foundation & Services):</strong></li>\n<li><code>Diagnostic Manager (DM)</code>: Standardisierter Plattform-Service (<code>ara::diag</code>), der den DoIP-Endpunkt terminiert und UDS-Services an die <code>Diagnostic application</code> routet.</li>\n<li><code>UCM Master (V-UCM)</code>: Zentrales Koordinationscluster für fahrzeugweite Update-Kampagnen (Abhängigkeitsprüfung, Kampagnen-Rollback, Orchestrierung).</li>\n<li><code>UCM</code>: Lokale Update-and-Configuration-Management-Instanz zur Aktualisierung der eigenen Adaptive Machine.</li>\n<li><code>ISO 22900-2 (D-PDU API)</code>: Standardisierte Abstraktionsschicht für hersteller- und hardwareunabhängige Kommunikationsverbindungen.</li>\n<li><code>VCI Module 1 (CAN)</code> & <code>VCI Module 2 (Ethernet)</code>: Virtual Communication Interface Treiberbausteine zur Protokollgenerierung.</li>\n</ul>\n<p class=\"fig-p\">#### Zielknoten (Targets)</p>\n<ul class=\"fig-list\">\n<li><code>Classic AUTOSAR ECU (CAN)</code>: Target-ECU, angebunden über <code>UDS on CAN</code> (ISO 14229 via ISO 15765-2 DoCAN).</li>\n<li><code>Classic AUTOSAR ECU (Ethernet)</code>: Target-ECU, angebunden über <code>UDS on DoIP</code> (ISO 14229 via ISO 13400).</li>\n<li><code>Physical box #2 (HW Element ECU)</code>: Heterogener Mehrkern-/Multiprozessorknoten mit koexistierenden Partitionen (<code>Classic AUTOSAR (ECU instance)</code> und <code>Non AUTOSAR</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Kommunikationspfade</p>\n<ul class=\"fig-list\">\n<li><strong>Tester $\\leftrightarrow$ DM:</strong> DoIP (ISO 13400) über Ethernet / CAN.</li>\n<li><strong>DM $\\leftrightarrow$ Diagnostic application:</strong> Standardisierte <code>ara::diag</code>-Interaktionsschnittstelle.</li>\n<li><strong>Diagnostic application $\\leftrightarrow$ UCM Master:</strong> Package Management Service Interface (<code>ara::ucm::pkgmgr</code>).</li>\n<li><strong>UCM Master $\\leftrightarrow$ VSM / Driver Interface:</strong> Inter-Process Communication via <code>ara::com</code> / Plattform-Zustandsmeldungen.</li>\n<li><strong>UCM Master $\\leftrightarrow$ Flashing Adapter:</strong> Sub-Orchestrierungsschnittstelle zur Ziel-Reprogrammierung.</li>\n<li><strong>Flashing Adapter $\\leftrightarrow$ ISO 22900-2:</strong> Standardisierte C-API der D-PDU API.</li>\n<li><strong>VCI-Module $\\leftrightarrow$ Ziel-ECUs:</strong> Bus-spezifische Transportprotokolle (DoCAN / DoIP).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Session-Aufbau & Übergabe:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <em>Garage tester</em> baut eine DoIP-Diagnosesitzung über das Fahrzeug-Gateway zum <em>Diagnostic Manager</em> auf.</li>\n<li>Der <em>Diagnostic Manager</em> leitet die Update-spezifischen Diagnosedaten an die <em>Diagnostic application</em> weiter.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kampagnen-Triggerung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <em>Diagnostic application</em> transferiert das Update-Paket (Vehicle Package) bzw. den Kampagnenbefehl an den <em>UCM Master</em> (Aufruf analog zu einem OTA-Backend-Trigger).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Precondition- & State-Validierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <em>UCM Master</em> prüft asynchron beim <em>Vehicle State Manager</em> die Freigabebedingungen (Sicherheitszustand, Fahrzeugstillstand, Update-Modus).</li>\n<li>Bei Bedarf erfolgt eine Rückmeldung/Freigabeanforderung über das <em>Driver Interface</em>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Target-Reprogrammierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach positiver Validierung instruiert der <em>UCM Master</em> den <em>Flashing Adapter</em>.</li>\n<li>Der <em>Flashing Adapter</em> baut über die <em>ISO 22900-2 D-PDU API</em> logische Kommunikationskanäle über das zuständige VCI-Modul auf.</li>\n<li>Ablauf der standardisierten UDS-Flashsequenz auf den Ziel-ECUs:</li>\n<li>Diagnostic Session Control (<code>0x10 02</code> - Programming Session)</li>\n<li>Security Access (<code>0x27</code>)</li>\n<li>Routine Control (<code>0x31</code> - Erase Memory)</li>\n<li>Request Download (<code>0x34</code>) & Transfer Data (<code>0x36</code>)</li>\n<li>Request Transfer Exit (<code>0x37</code>) & Check Routine / Signature Verification (<code>0x31</code>)</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchronisation & Statusrückmeldung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <em>Flashing Adapter</em> meldet den Abschluss an den <em>UCM Master</em>.</li>\n<li>Der <em>UCM Master</em> finalisiert die Gesamtkampagne (Aktivierung/Commit oder Rollback) und meldet den Status über die <em>Diagnostic application</em> und den <em>Diagnostic Manager</em> an den <em>Garage tester</em> zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abbruchbedingungen:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Statuswechsel des VSM (z. B. Signal <code>Vehicle Driving</code> oder Unterspannung) $\\rightarrow$ Abbruch des UCM Master mit sicherem Rollback.</li>\n<li>UDS Negative Response Codes (NRCs, z. B. <code>$7F 36 78</code> Time-out oder <code>$7F 27 35</code> Invalid Key) $\\rightarrow$ Abbruch der sequentiellen PDU-Übertragung im Flashing Adapter.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Vertrag (Adaptive Stack):</strong></li>\n<li>Entwickler der <em>Diagnostic application</em> müssen sowohl die Konsumenten-Rolle für <code>ara::diag</code> als auch die Client-Rolle für die <code>ara::ucm::pkgmgr</code>-Schnittstellen implementieren.</li>\n<li>Der <em>Flashing Adapter</em> ist herstellerspezifisch: Er wandelt die abstrakten Update-Instruktionen des UCM Masters in konkrete UDS-Sequenzen um und bindet gegen die POSIX-konforme Implementierung der <code>ISO 22900-2</code> C-API.</li>\n<li><strong>Entkopplung der Classic Platform (Classic Stack):</strong></li>\n<li>Target-ECUs mit Classic AUTOSAR benötigen keine Erweiterung für Adaptive AUTOSAR oder V-UCM. Sie werden rein normativ über Standard-Classic-Basissoftware (BSW: <code>Dcm</code>, <code>CanTp</code>, <code>DoIP</code>, <code>Fls</code> und Standard-Bootloader) betrieben.</li>\n<li><strong>Hardwareressourcen & VCI-Layer:</strong></li>\n<li>Der Einsatz der <em>ISO 22900-2 (D-PDU API)</em> isoliert den Flashing Adapter von der physischen Netzwerktopologie (CAN-Controller-Hardware, Ethernet-Switches). Die VCI-Treiber müssen auf der Linux/QNX-Ebene der Adaptive Machine als Shared Libraries (<code>.so</code>) bereitgestellt werden.</li>\n<li><strong>Safety & Security:</strong></li>\n<li>Die Schnittstelle zum <em>Vehicle State Manager</em> ist sicherheitsrelevant (ASIL-Einstufung nach ISO 26262), um versehentliches Reprogrammieren während des Fahrbetriebs auszuschließen.</li>\n<li>Das Security-Konzept verlangt, dass Security-Access-Tokens oder Seed/Key-Verfahren entweder in der <em>Diagnostic application</em>, im <em>Flashing Adapter</em> (z. B. via <code>ara::crypto</code>) oder transparent über den <em>Garage tester</em> abgewickelt werden.</li>\n</ul>"}, {"id": "FIG-3e71058d5bdda3dc", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> System- und Komponenten-Architekturdiagramm (Deployment- und Integrationsszenario).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der verteilten Aktualisierung von Classic-AUTOSAR- und Non-AUTOSAR-Steuergeräten über das fahrzeugzentrale Update- und Konfigurationsmanagement (Vehicle-UCM / V-UCM) der Adaptive Platform unter Verwendung eines externen Werkstattesters (<em>Garage Tester</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Zeigt die Entkopplung zwischen externem Diagnosezugang und interner Flash-Orchestrierung. Der externe Tester flasht Sub-ECUs nicht direkt; stattdessen agiert eine bordeigene <code>Diagnostic application</code> als lokaler Client (äquivalent zu einem Cloud-basierten OTA-Client), der den <code>UCM Master</code> zur fahrzeugweiten Kampagnenausführung triggert. Die physische Reprogrammierung heterogener Ziel-ECUs wird über einen <code>Flashing Adapter</code> via standardisierter <code>ISO 22900-2 (D-PDU API)</code> gekapselt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Externe Diagnose-Infrastruktur</p>\n<ul class=\"fig-list\">\n<li><strong>Garage tester:</strong> Off-Board-Diagnosetester, physikalisch über ein <code>Communication medium</code> angebunden.</li>\n<li><strong>Communication channel:</strong> Fahrzeug-Gateway-Zugang via Ethernet oder CAN/DoCAN-Bus.</li>\n</ul>\n<p class=\"fig-p\">#### Adaptive AUTOSAR Machine (Host für V-UCM)</p>\n<ul class=\"fig-list\">\n<li><strong>Applikationsebene (Adaptive Applications):</strong></li>\n<li><code>Diagnostic application</code>: Adaptiver Service/Prozess; nimmt Diagnoseanfragen des Testers entgegen und agiert gegenüber dem <code>UCM Master</code> als Update-Client (<em>acts like an OTA Client</em>).</li>\n<li><code>Flashing Adapter</code>: Applikative Schicht zur Kapselung herstellerspezifischer UDS-Flasbabläufe (Download-Sequenzen, Signature-Checks) für externe Ziel-Steuergeräte.</li>\n<li><code>Vehicle State Manager (VSM)</code>: Überwacht und validiert fahrzeugweite Sicherheitszustände (z. B. Stillstand, Klemmenstatus, Batterie-Mindestspannung).</li>\n<li><code>Driver Interface</code>: Applikation zur Benutzerinteraktion (Fahrerquittierung, Statusanzeigen).</li>\n<li><strong>Plattform-/Cluster-Ebene (Adaptive Foundation & Services):</strong></li>\n<li><code>Diagnostic Manager (DM)</code>: Standardisierter Plattform-Service (<code>ara::diag</code>), der den DoIP-Endpunkt terminiert und UDS-Services an die <code>Diagnostic application</code> routet.</li>\n<li><code>UCM Master (V-UCM)</code>: Zentrales Koordinationscluster für fahrzeugweite Update-Kampagnen (Abhängigkeitsprüfung, Kampagnen-Rollback, Orchestrierung).</li>\n<li><code>UCM</code>: Lokale Update-and-Configuration-Management-Instanz zur Aktualisierung der eigenen Adaptive Machine.</li>\n<li><code>ISO 22900-2 (D-PDU API)</code>: Standardisierte Abstraktionsschicht für hersteller- und hardwareunabhängige Kommunikationsverbindungen.</li>\n<li><code>VCI Module 1 (CAN)</code> & <code>VCI Module 2 (Ethernet)</code>: Virtual Communication Interface Treiberbausteine zur Protokollgenerierung.</li>\n</ul>\n<p class=\"fig-p\">#### Zielknoten (Targets)</p>\n<ul class=\"fig-list\">\n<li><code>Classic AUTOSAR ECU (CAN)</code>: Target-ECU, angebunden über <code>UDS on CAN</code> (ISO 14229 via ISO 15765-2 DoCAN).</li>\n<li><code>Classic AUTOSAR ECU (Ethernet)</code>: Target-ECU, angebunden über <code>UDS on DoIP</code> (ISO 14229 via ISO 13400).</li>\n<li><code>Physical box #2 (HW Element ECU)</code>: Heterogener Mehrkern-/Multiprozessorknoten mit koexistierenden Partitionen (<code>Classic AUTOSAR (ECU instance)</code> und <code>Non AUTOSAR</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Kommunikationspfade</p>\n<ul class=\"fig-list\">\n<li><strong>Tester $\\leftrightarrow$ DM:</strong> DoIP (ISO 13400) über Ethernet / CAN.</li>\n<li><strong>DM $\\leftrightarrow$ Diagnostic application:</strong> Standardisierte <code>ara::diag</code>-Interaktionsschnittstelle.</li>\n<li><strong>Diagnostic application $\\leftrightarrow$ UCM Master:</strong> Package Management Service Interface (<code>ara::ucm::pkgmgr</code>).</li>\n<li><strong>UCM Master $\\leftrightarrow$ VSM / Driver Interface:</strong> Inter-Process Communication via <code>ara::com</code> / Plattform-Zustandsmeldungen.</li>\n<li><strong>UCM Master $\\leftrightarrow$ Flashing Adapter:</strong> Sub-Orchestrierungsschnittstelle zur Ziel-Reprogrammierung.</li>\n<li><strong>Flashing Adapter $\\leftrightarrow$ ISO 22900-2:</strong> Standardisierte C-API der D-PDU API.</li>\n<li><strong>VCI-Module $\\leftrightarrow$ Ziel-ECUs:</strong> Bus-spezifische Transportprotokolle (DoCAN / DoIP).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Session-Aufbau & Übergabe:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <em>Garage tester</em> baut eine DoIP-Diagnosesitzung über das Fahrzeug-Gateway zum <em>Diagnostic Manager</em> auf.</li>\n<li>Der <em>Diagnostic Manager</em> leitet die Update-spezifischen Diagnosedaten an die <em>Diagnostic application</em> weiter.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kampagnen-Triggerung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <em>Diagnostic application</em> transferiert das Update-Paket (Vehicle Package) bzw. den Kampagnenbefehl an den <em>UCM Master</em> (Aufruf analog zu einem OTA-Backend-Trigger).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Precondition- & State-Validierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <em>UCM Master</em> prüft asynchron beim <em>Vehicle State Manager</em> die Freigabebedingungen (Sicherheitszustand, Fahrzeugstillstand, Update-Modus).</li>\n<li>Bei Bedarf erfolgt eine Rückmeldung/Freigabeanforderung über das <em>Driver Interface</em>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Target-Reprogrammierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach positiver Validierung instruiert der <em>UCM Master</em> den <em>Flashing Adapter</em>.</li>\n<li>Der <em>Flashing Adapter</em> baut über die <em>ISO 22900-2 D-PDU API</em> logische Kommunikationskanäle über das zuständige VCI-Modul auf.</li>\n<li>Ablauf der standardisierten UDS-Flashsequenz auf den Ziel-ECUs:</li>\n<li>Diagnostic Session Control (<code>0x10 02</code> - Programming Session)</li>\n<li>Security Access (<code>0x27</code>)</li>\n<li>Routine Control (<code>0x31</code> - Erase Memory)</li>\n<li>Request Download (<code>0x34</code>) & Transfer Data (<code>0x36</code>)</li>\n<li>Request Transfer Exit (<code>0x37</code>) & Check Routine / Signature Verification (<code>0x31</code>)</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchronisation & Statusrückmeldung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <em>Flashing Adapter</em> meldet den Abschluss an den <em>UCM Master</em>.</li>\n<li>Der <em>UCM Master</em> finalisiert die Gesamtkampagne (Aktivierung/Commit oder Rollback) und meldet den Status über die <em>Diagnostic application</em> und den <em>Diagnostic Manager</em> an den <em>Garage tester</em> zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abbruchbedingungen:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Statuswechsel des VSM (z. B. Signal <code>Vehicle Driving</code> oder Unterspannung) $\\rightarrow$ Abbruch des UCM Master mit sicherem Rollback.</li>\n<li>UDS Negative Response Codes (NRCs, z. B. <code>$7F 36 78</code> Time-out oder <code>$7F 27 35</code> Invalid Key) $\\rightarrow$ Abbruch der sequentiellen PDU-Übertragung im Flashing Adapter.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Vertrag (Adaptive Stack):</strong></li>\n<li>Entwickler der <em>Diagnostic application</em> müssen sowohl die Konsumenten-Rolle für <code>ara::diag</code> als auch die Client-Rolle für die <code>ara::ucm::pkgmgr</code>-Schnittstellen implementieren.</li>\n<li>Der <em>Flashing Adapter</em> ist herstellerspezifisch: Er wandelt die abstrakten Update-Instruktionen des UCM Masters in konkrete UDS-Sequenzen um und bindet gegen die POSIX-konforme Implementierung der <code>ISO 22900-2</code> C-API.</li>\n<li><strong>Entkopplung der Classic Platform (Classic Stack):</strong></li>\n<li>Target-ECUs mit Classic AUTOSAR benötigen keine Erweiterung für Adaptive AUTOSAR oder V-UCM. Sie werden rein normativ über Standard-Classic-Basissoftware (BSW: <code>Dcm</code>, <code>CanTp</code>, <code>DoIP</code>, <code>Fls</code> und Standard-Bootloader) betrieben.</li>\n<li><strong>Hardwareressourcen & VCI-Layer:</strong></li>\n<li>Der Einsatz der <em>ISO 22900-2 (D-PDU API)</em> isoliert den Flashing Adapter von der physischen Netzwerktopologie (CAN-Controller-Hardware, Ethernet-Switches). Die VCI-Treiber müssen auf der Linux/QNX-Ebene der Adaptive Machine als Shared Libraries (<code>.so</code>) bereitgestellt werden.</li>\n<li><strong>Safety & Security:</strong></li>\n<li>Die Schnittstelle zum <em>Vehicle State Manager</em> ist sicherheitsrelevant (ASIL-Einstufung nach ISO 26262), um versehentliches Reprogrammieren während des Fahrbetriebs auszuschließen.</li>\n<li>Das Security-Konzept verlangt, dass Security-Access-Tokens oder Seed/Key-Verfahren entweder in der <em>Diagnostic application</em>, im <em>Flashing Adapter</em> (z. B. via <code>ara::crypto</code>) oder transparent über den <em>Garage tester</em> abgewickelt werden.</li>\n</ul>"}, {"id": "FIG-f062f1ff3a96b7bd", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> System- und Komponenten-Architekturdiagramm (Deployment- und Integrationsszenario).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der verteilten Aktualisierung von Classic-AUTOSAR- und Non-AUTOSAR-Steuergeräten über das fahrzeugzentrale Update- und Konfigurationsmanagement (Vehicle-UCM / V-UCM) der Adaptive Platform unter Verwendung eines externen Werkstattesters (<em>Garage Tester</em>).</li>\n<li><strong>Funktionale Einordnung:</strong> Zeigt die Entkopplung zwischen externem Diagnosezugang und interner Flash-Orchestrierung. Der externe Tester flasht Sub-ECUs nicht direkt; stattdessen agiert eine bordeigene <code>Diagnostic application</code> als lokaler Client (äquivalent zu einem Cloud-basierten OTA-Client), der den <code>UCM Master</code> zur fahrzeugweiten Kampagnenausführung triggert. Die physische Reprogrammierung heterogener Ziel-ECUs wird über einen <code>Flashing Adapter</code> via standardisierter <code>ISO 22900-2 (D-PDU API)</code> gekapselt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Externe Diagnose-Infrastruktur</p>\n<ul class=\"fig-list\">\n<li><strong>Garage tester:</strong> Off-Board-Diagnosetester, physikalisch über ein <code>Communication medium</code> angebunden.</li>\n<li><strong>Communication channel:</strong> Fahrzeug-Gateway-Zugang via Ethernet oder CAN/DoCAN-Bus.</li>\n</ul>\n<p class=\"fig-p\">#### Adaptive AUTOSAR Machine (Host für V-UCM)</p>\n<ul class=\"fig-list\">\n<li><strong>Applikationsebene (Adaptive Applications):</strong></li>\n<li><code>Diagnostic application</code>: Adaptiver Service/Prozess; nimmt Diagnoseanfragen des Testers entgegen und agiert gegenüber dem <code>UCM Master</code> als Update-Client (<em>acts like an OTA Client</em>).</li>\n<li><code>Flashing Adapter</code>: Applikative Schicht zur Kapselung herstellerspezifischer UDS-Flasbabläufe (Download-Sequenzen, Signature-Checks) für externe Ziel-Steuergeräte.</li>\n<li><code>Vehicle State Manager (VSM)</code>: Überwacht und validiert fahrzeugweite Sicherheitszustände (z. B. Stillstand, Klemmenstatus, Batterie-Mindestspannung).</li>\n<li><code>Driver Interface</code>: Applikation zur Benutzerinteraktion (Fahrerquittierung, Statusanzeigen).</li>\n<li><strong>Plattform-/Cluster-Ebene (Adaptive Foundation & Services):</strong></li>\n<li><code>Diagnostic Manager (DM)</code>: Standardisierter Plattform-Service (<code>ara::diag</code>), der den DoIP-Endpunkt terminiert und UDS-Services an die <code>Diagnostic application</code> routet.</li>\n<li><code>UCM Master (V-UCM)</code>: Zentrales Koordinationscluster für fahrzeugweite Update-Kampagnen (Abhängigkeitsprüfung, Kampagnen-Rollback, Orchestrierung).</li>\n<li><code>UCM</code>: Lokale Update-and-Configuration-Management-Instanz zur Aktualisierung der eigenen Adaptive Machine.</li>\n<li><code>ISO 22900-2 (D-PDU API)</code>: Standardisierte Abstraktionsschicht für hersteller- und hardwareunabhängige Kommunikationsverbindungen.</li>\n<li><code>VCI Module 1 (CAN)</code> & <code>VCI Module 2 (Ethernet)</code>: Virtual Communication Interface Treiberbausteine zur Protokollgenerierung.</li>\n</ul>\n<p class=\"fig-p\">#### Zielknoten (Targets)</p>\n<ul class=\"fig-list\">\n<li><code>Classic AUTOSAR ECU (CAN)</code>: Target-ECU, angebunden über <code>UDS on CAN</code> (ISO 14229 via ISO 15765-2 DoCAN).</li>\n<li><code>Classic AUTOSAR ECU (Ethernet)</code>: Target-ECU, angebunden über <code>UDS on DoIP</code> (ISO 14229 via ISO 13400).</li>\n<li><code>Physical box #2 (HW Element ECU)</code>: Heterogener Mehrkern-/Multiprozessorknoten mit koexistierenden Partitionen (<code>Classic AUTOSAR (ECU instance)</code> und <code>Non AUTOSAR</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Schnittstellen & Kommunikationspfade</p>\n<ul class=\"fig-list\">\n<li><strong>Tester $\\leftrightarrow$ DM:</strong> DoIP (ISO 13400) über Ethernet / CAN.</li>\n<li><strong>DM $\\leftrightarrow$ Diagnostic application:</strong> Standardisierte <code>ara::diag</code>-Interaktionsschnittstelle.</li>\n<li><strong>Diagnostic application $\\leftrightarrow$ UCM Master:</strong> Package Management Service Interface (<code>ara::ucm::pkgmgr</code>).</li>\n<li><strong>UCM Master $\\leftrightarrow$ VSM / Driver Interface:</strong> Inter-Process Communication via <code>ara::com</code> / Plattform-Zustandsmeldungen.</li>\n<li><strong>UCM Master $\\leftrightarrow$ Flashing Adapter:</strong> Sub-Orchestrierungsschnittstelle zur Ziel-Reprogrammierung.</li>\n<li><strong>Flashing Adapter $\\leftrightarrow$ ISO 22900-2:</strong> Standardisierte C-API der D-PDU API.</li>\n<li><strong>VCI-Module $\\leftrightarrow$ Ziel-ECUs:</strong> Bus-spezifische Transportprotokolle (DoCAN / DoIP).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Session-Aufbau & Übergabe:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <em>Garage tester</em> baut eine DoIP-Diagnosesitzung über das Fahrzeug-Gateway zum <em>Diagnostic Manager</em> auf.</li>\n<li>Der <em>Diagnostic Manager</em> leitet die Update-spezifischen Diagnosedaten an die <em>Diagnostic application</em> weiter.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Kampagnen-Triggerung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die <em>Diagnostic application</em> transferiert das Update-Paket (Vehicle Package) bzw. den Kampagnenbefehl an den <em>UCM Master</em> (Aufruf analog zu einem OTA-Backend-Trigger).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Precondition- & State-Validierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <em>UCM Master</em> prüft asynchron beim <em>Vehicle State Manager</em> die Freigabebedingungen (Sicherheitszustand, Fahrzeugstillstand, Update-Modus).</li>\n<li>Bei Bedarf erfolgt eine Rückmeldung/Freigabeanforderung über das <em>Driver Interface</em>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Target-Reprogrammierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach positiver Validierung instruiert der <em>UCM Master</em> den <em>Flashing Adapter</em>.</li>\n<li>Der <em>Flashing Adapter</em> baut über die <em>ISO 22900-2 D-PDU API</em> logische Kommunikationskanäle über das zuständige VCI-Modul auf.</li>\n<li>Ablauf der standardisierten UDS-Flashsequenz auf den Ziel-ECUs:</li>\n<li>Diagnostic Session Control (<code>0x10 02</code> - Programming Session)</li>\n<li>Security Access (<code>0x27</code>)</li>\n<li>Routine Control (<code>0x31</code> - Erase Memory)</li>\n<li>Request Download (<code>0x34</code>) & Transfer Data (<code>0x36</code>)</li>\n<li>Request Transfer Exit (<code>0x37</code>) & Check Routine / Signature Verification (<code>0x31</code>)</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchronisation & Statusrückmeldung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <em>Flashing Adapter</em> meldet den Abschluss an den <em>UCM Master</em>.</li>\n<li>Der <em>UCM Master</em> finalisiert die Gesamtkampagne (Aktivierung/Commit oder Rollback) und meldet den Status über die <em>Diagnostic application</em> und den <em>Diagnostic Manager</em> an den <em>Garage tester</em> zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abbruchbedingungen:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Statuswechsel des VSM (z. B. Signal <code>Vehicle Driving</code> oder Unterspannung) $\\rightarrow$ Abbruch des UCM Master mit sicherem Rollback.</li>\n<li>UDS Negative Response Codes (NRCs, z. B. <code>$7F 36 78</code> Time-out oder <code>$7F 27 35</code> Invalid Key) $\\rightarrow$ Abbruch der sequentiellen PDU-Übertragung im Flashing Adapter.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>API-Vertrag (Adaptive Stack):</strong></li>\n<li>Entwickler der <em>Diagnostic application</em> müssen sowohl die Konsumenten-Rolle für <code>ara::diag</code> als auch die Client-Rolle für die <code>ara::ucm::pkgmgr</code>-Schnittstellen implementieren.</li>\n<li>Der <em>Flashing Adapter</em> ist herstellerspezifisch: Er wandelt die abstrakten Update-Instruktionen des UCM Masters in konkrete UDS-Sequenzen um und bindet gegen die POSIX-konforme Implementierung der <code>ISO 22900-2</code> C-API.</li>\n<li><strong>Entkopplung der Classic Platform (Classic Stack):</strong></li>\n<li>Target-ECUs mit Classic AUTOSAR benötigen keine Erweiterung für Adaptive AUTOSAR oder V-UCM. Sie werden rein normativ über Standard-Classic-Basissoftware (BSW: <code>Dcm</code>, <code>CanTp</code>, <code>DoIP</code>, <code>Fls</code> und Standard-Bootloader) betrieben.</li>\n<li><strong>Hardwareressourcen & VCI-Layer:</strong></li>\n<li>Der Einsatz der <em>ISO 22900-2 (D-PDU API)</em> isoliert den Flashing Adapter von der physischen Netzwerktopologie (CAN-Controller-Hardware, Ethernet-Switches). Die VCI-Treiber müssen auf der Linux/QNX-Ebene der Adaptive Machine als Shared Libraries (<code>.so</code>) bereitgestellt werden.</li>\n<li><strong>Safety & Security:</strong></li>\n<li>Die Schnittstelle zum <em>Vehicle State Manager</em> ist sicherheitsrelevant (ASIL-Einstufung nach ISO 26262), um versehentliches Reprogrammieren während des Fahrbetriebs auszuschließen.</li>\n<li>Das Security-Konzept verlangt, dass Security-Access-Tokens oder Seed/Key-Verfahren entweder in der <em>Diagnostic application</em>, im <em>Flashing Adapter</em> (z. B. via <code>ara::crypto</code>) oder transparent über den <em>Garage tester</em> abgewickelt werden.</li>\n</ul>"}], "trans": [{"from": "FIG-381e523b53e2290b", "to": "FIG-3e71058d5bdda3dc", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-3e71058d5bdda3dc", "to": "FIG-f062f1ff3a96b7bd", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
